/**
 * @name Potential code execution via eval/exec in cffi
 * @description Detects flows of remote input into eval/exec or compile used by cffi helper modules.
 * @kind path-problem
 * @problem.severity error
 * @id py/cffi-code-execution
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) { source instanceof RemoteFlowSource }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call, DataFlow::Node arg0 |
      // Calls to the built-in eval/exec/compile
      call = API::builtin(["eval", "exec", "compile"]).getACall() and
      arg0 = call.getArg(0) and
      sink = arg0
    )
  }
}

module ExecFlow = TaintTracking::Global<ExecConfig>;
import ExecFlow::PathGraph

from ExecFlow::PathNode source, ExecFlow::PathNode sink
where ExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches $@.", sink, "eval/exec/compile"
